scripts.s2_starter.py:
# Candidate B: linearly implicit Euler extrapolation (harmonic sequence, Neville), T=J0 frozen at t_init, forward-only.
# Nodes tau+c_i*h0 with tau=t_init+h0*(-c_min)=t_init+h0 -> offsets from t_init: h0*(1+c_i) = 0,0.5,1,1.4,1.8,2 (all >=0).
import numpy as np, math, scipy.linalg as sla, json, sys
C=np.array([-1.0,-0.5,0.0,0.4,0.8,1.0])
def limex_macro(f,T,t,y,H,k):
    n=y.size; ns=list(range(1,k+1)); Tab=[]; cost=dict(lu=0,f=0)
    for nj in ns:
        h=H/nj; lu=sla.lu_factor(np.eye(n)-h*T); cost['lu']+=1; z=y.copy(); tt=t
        for _ in range(nj):
            d=sla.lu_solve(lu,h*f(tt,z)); cost['f']+=1; z=z+d; tt+=h
        Tab.append([z])
        for l in range(1,len(Tab)):
            prev=Tab[-1][l-1]; old=Tab[-2][l-1]
            Tab[-1].append(prev+(prev-old)/(ns[len(Tab)-1]/ns[len(Tab)-1-l]-1))
    return Tab[-1][-1],cost
def starter(f,J,t_init,y0,h0,k):
    T=J(t_init,y0); offs=h0*(1+C); order=np.argsort(offs)   # offs already ascending
    Y=np.zeros((6,y0.size)); t=t_init; y=y0.copy(); cost=dict(lu=0,f=0,jac=1)
    for i in range(6):
        H=t_init+offs[i]-t
        if H>1e-15:
            y,cc=limex_macro(f,T,t,y,H,k); t+=H; cost['lu']+=cc['lu']; cost['f']+=cc['f']
        Y[i]=y
    return Y,cost
def make_PR(lam,amp):
    f=lambda t,y: lam*(y-math.sin(t))+math.cos(t)
    yex=lambda t: np.array([math.sin(t)+amp*math.exp(lam*t)])
    return f,(lambda t,y: np.array([[lam]])),yex
def make_LIN3():
    rs=np.random.RandomState(3); Q,_=np.linalg.qr(rs.randn(3,3)); A=Q@np.diag([-1.,-50.,-1000.])@Q.T
    y0=np.array([1.,-2.,.5]); return (lambda t,y:A@y),(lambda t,y:A),(lambda t: sla.expm(A*t)@y0),y0
def fit(h,e):
    p=np.polyfit(np.log10(h),np.log10(e),1); return float(p[0])
if __name__=='__main__':
    res=[]
    probs={'PR_lam-1(amp1)':(*make_PR(-1.,1.),),'PR_lam-1000(amp0)':(*make_PR(-1000.,0.),),'PR_lam-1000(amp1)':(*make_PR(-1000.,1.),),'LIN3(-1,-50,-1000)':None}
    for name in ['PR_lam-1(amp1)','PR_lam-1000(amp0)','PR_lam-1000(amp1)','LIN3(-1,-50,-1000)']:
        if name.startswith('LIN3'):
            f,J,yex,y0=make_LIN3()
        else:
            f,J,yex=probs[name]; y0=yex(0.0)
        hs=[0.2,0.1,0.05,0.025,0.0125,0.00625] if name!='PR_lam-1(amp1)' else [0.4,0.2,0.1,0.05,0.025]
        for k in [4,5,6]:
            errs=[]
            per_node=[]
            for h0 in hs:
                Y,cost=starter(f,J,0.0,y0,h0,k)
                ex=np.array([yex(h0*(1+c)) for c in C])
                e=np.abs(Y-ex).max(axis=1); per_node.append(e.tolist()); errs.append(e.max())
            pn=[]
            for i in range(1,6):
                col=np.array([r[i] for r in per_node]); ok=col>1e-14
                pn.append(fit(np.array(hs)[ok],col[ok]) if ok.sum()>=3 else None)
            # local slopes between consecutive h
            loc=[math.log2(errs[i]/errs[i+1]) if errs[i+1]>0 and errs[i]>0 else None for i in range(len(hs)-1)]
            res.append(dict(problem=name,cols=k,h0=hs,maxerr=errs,fit_order_max=fit(np.array(hs)[np.array(errs)>1e-14],np.array(errs)[np.array(errs)>1e-14]) if sum(np.array(errs)>1e-14)>=3 else None,local_slopes_log2=loc,per_node_fit_nodes2_6=pn,cost=cost))
            print(name,'k=',k,'h0lam=',None,'maxerr',['%.2e'%e for e in errs],'slopes',[None if l is None else round(l,2) for l in loc],'cost',cost)
    json.dump(res,open(sys.argv[1],'w'),indent=1)

scripts.s5_ppsw.py:
# PPSW1-6b prototype (coefficients: closed form route2 from PW04_PPSW1_6BC_VERIFICATION.json ppsw_core.py, node-row V convention; same as s05_global.py)
# with starter variants; grid: t_init=0, tau=h0 (shifted start), nodes of Y_0 = tau + c_i h0. Also estimator exponent test.
import sys, math, random, numpy as np, scipy.linalg as sla, json
from importlib.machinery import SourceFileLoader
m2=SourceFileLoader('s2',sys.argv[2]).load_module(); m3=SourceFileLoader('s3',sys.argv[3]).load_module()
G=0.619411975066250516310763374003; C=m2.C; s=6
Vn=np.array([[C[i]**j for j in range(s)] for i in range(s)]); Vi=np.linalg.inv(Vn)
Pm=np.array([[math.comb(j,i) for j in range(s)] for i in range(s)],float); Dm=np.diag(np.arange(1,s+1).astype(float))
F0=np.zeros((s,s)); 
for i in range(1,s): F0[i,i-1]=1
def coeffs(sig):
    S=np.diag(sig**np.arange(s)); Th=Vn@S@Pm@Vi; Gam=-G*Th; E=-Vn@Dm@F0.T@Vi
    beta=Vn@F0@S@np.linalg.inv(Dm)@Vi; B=(np.eye(s)+G*E)@Th+sig*(beta@E); return B,beta-Gam,Gam
def pred_w(sig):  # S3 weights, nodes c_2..c_6 at x=1+sig
    x=1+sig; nd=C[1:]; w=[]
    for j in range(5):
        v=1.0
        for k in range(5):
            if k!=j: v*=(x-nd[k])/(nd[j]-nd[k])
        w.append(v)
    return np.array(w)
def run(f,J,yex,start,N,rseq=None,Tend=1.0):
    w=np.ones(N) if rseq is None else np.exp(np.concatenate([[0.],np.cumsum(np.log(rseq[:N-1]))]))
    h=w*(Tend/np.sum(w)); h0=h[0]; tau=h0
    t=np.concatenate([[tau],tau+np.cumsum(h)])
    y0=yex(0.0)
    if start=='exact': Yp=np.array([yex(tau+h0*c) for c in C])
    elif start.startswith('radau'): Yp,_=m3.dense_start(f,J,0.0,y0,h0,int(start[5:]))
    elif start.startswith('limex'): Yp,_=m2.starter(f,J,0.0,y0,h0,int(start[5:]))
    Fp=np.array([f(t[0]+h0*C[j],Yp[j]) for j in range(s)]); est=[]
    for m in range(1,N):
        hm=h[m]; sig=hm/h[m-1]; B,A,Gam=coeffs(sig); Tm=J(t[m],Yp[-1]); n=Tm.shape[0]
        lu=sla.lu_factor(np.eye(n)-G*hm*Tm)
        R=B@Yp+hm*(Gam@(Yp@Tm.T))+hm*(A@Fp)
        Yn=np.array([sla.lu_solve(lu,R[i]) for i in range(s)])
        est.append((m,float(np.max(np.abs(Yn[-1]-pred_w(sig)@Yp[1:]))),float(np.max(np.abs(Yn[-1]-yex(t[m]+hm))))))
        Yp=Yn; Fp=np.array([f(t[m]+hm*C[i],Yp[i]) for i in range(s)])
    return float(np.max(np.abs(Yp[-1]-yex(t[N])))),est,float(np.max(h))
def fit(H,e):
    ok=np.array(e)>1e-15
    return float(np.polyfit(np.log10(np.array(H)[ok]),np.log10(np.array(e)[ok]),1)[0]) if ok.sum()>=3 else None
def ratio_seq(seed,lo,hi,L):
    r=random.Random(seed); l=0.; o=[]
    for _ in range(L):
        for _t in range(1000):
            sg=r.uniform(lo,hi)
            if abs(l+math.log(sg))<=0.5: break
        else: sg=1.
        l+=math.log(sg); o.append(sg)
    return np.array(o)
def PRvec(lams):
    rs=np.random.RandomState(5); Q,_=np.linalg.qr(rs.randn(len(lams),len(lams))); A=Q@np.diag(lams)@Q.T
    g=lambda t: np.array([math.sin(t),math.cos(2*t)][:len(lams)]); gp=lambda t: np.array([math.cos(t),-2*math.sin(2*t)][:len(lams)])
    return (lambda t,y:A@(y-g(t))+gp(t)),(lambda t,y:A),g
if __name__=='__main__':
    Ns=[16,32,64,128,256]; out=[]
    probs={'PR_lam-1(amp1)':m2.make_PR(-1.,1.),'PR_lam-1000(amp0)':m2.make_PR(-1000.,0.),'PRvec2_(-1,-1000)_smooth':PRvec([-1.,-1000.])}
    for pn,(f,J,yex) in probs.items():
        for sname,rs in [('uniform',None),('rand0.5-1.10',ratio_seq(11,.5,1.1,256))]:
            for st in ['exact','radau5','radau3','limex5']:
                errs=[];Hs=[];ests=None
                for N in Ns:
                    e,est,H=run(f,J,yex,st,N,rs); errs.append(e); Hs.append(H)
                    if rs is None and N==64: ests=est
                row=dict(problem=pn,sigma=sname,start=st,N=Ns,H=Hs,err=errs,order_fit=fit(Hs,errs),local_slopes=[round(math.log2(errs[i]/errs[i+1]),2) if errs[i+1]>0 else None for i in range(len(Ns)-1)])
                out.append(row); print(pn,sname,st,'fit',None if row['order_fit'] is None else round(row['order_fit'],2),['%.1e'%e for e in errs],row['local_slopes'])
    # estimator exponent: uniform grid, exact start, PR lam=-1 (y^(5)!=0), mid-run value m=N//2
    f,J,yex=probs['PR_lam-1(amp1)']; er=[]
    Ns2=[16,32,64,128]; Hs=[];E=[];T=[]
    for N in Ns2:
        e,est,H=run(f,J,yex,'exact',N,None); k=len(est)//2; Hs.append(H); E.append(est[k][1]); T.append(est[k][2])
    er=dict(N=Ns2,H=Hs,est=E,true_err_Yms=T,est_fit=fit(Hs,E),trueerr_fit=fit(Hs,T)); out.append(dict(estimator=er)); print('ESTIMATOR',er)
    json.dump(out,open(sys.argv[1],'w'),indent=1)
